"use client";

import { cn } from "../../internal";
import { cva, VariantProps } from "class-variance-authority";
import { Check, Minus } from "lucide-react";
import * as CheckboxPrimitive from "@radix-ui/react-checkbox";
import * as React from "react";

// Define the variants for the Checkbox using cva.
const checkboxVariants = cva(
  `
    group peer bg-background shrink-0 rounded-sm ring-offset-background
    border-2 border-solid border-input
    focus-visible:outline-none focus-visible:ring-0 focus-visible:ring-offset-0
    disabled:cursor-not-allowed disabled:opacity-50
    aria-invalid:border-destructive/60! aria-invalid:ring-destructive/10 dark:aria-invalid:border-destructive!
    in-data-[invalid=true]:border-destructive/60! in-data-[invalid=true]:ring-destructive/10 dark:in-data-[invalid=true]:border-destructive!
    data-[state=checked]:border-primary! data-[state=checked]:bg-primary data-[state=checked]:text-primary-foreground
    data-[state=indeterminate]:border-primary! data-[state=indeterminate]:bg-primary data-[state=indeterminate]:text-primary-foreground
    `,
  {
    variants: {
      size: {
        sm: "size-4.5 [&_svg]:size-3",
        md: "size-5 [&_svg]:size-3.5",
        lg: "size-5.5 [&_svg]:size-4",
      },
    },
    defaultVariants: {
      size: "md",
    },
  },
);

function Checkbox({
  className,
  size,
  ...props
}: React.ComponentProps<typeof CheckboxPrimitive.Root> &
  VariantProps<typeof checkboxVariants>) {
  return (
    <CheckboxPrimitive.Root
      data-slot="checkbox"
      className={cn(checkboxVariants({ size }), className)}
      {...props}>
      <CheckboxPrimitive.Indicator
        className={cn("flex items-center justify-center text-current")}>
        <Check className="group-data-[state=indeterminate]:hidden" />
        <Minus className="hidden group-data-[state=indeterminate]:block" />
      </CheckboxPrimitive.Indicator>
    </CheckboxPrimitive.Root>
  );
}

export { Checkbox };

/**
 * Browser environment helpers.
 * Keep this module dependency-free to allow safe imports anywhere.
 */

/** Return type of `globalThis.setTimeout` (DOM `number` + `NodeJS.Timeout` under mixed typings). */
export type GlobalTimeoutId = ReturnType<typeof globalThis.setTimeout>;

export function getBrowserWindow(): Window | null {
  return globalThis.window ?? null;
}

export function isBrowserEnvironment(): boolean {
  return getBrowserWindow() !== null;
}

/**
 * Same-origin iframe document only. `contentWindow.document` throws SecurityError
 * when the frame is opaque (WP 7.1 DIP / cross-origin). `contentDocument` is null.
 */
export function getSameOriginIframeDocument(
  iframe: HTMLIFrameElement | null | undefined,
): Document | null {
  if (!iframe) {
    return null;
  }

  try {
    return iframe.contentDocument ?? null;
  } catch {
    return null;
  }
}

/**
 * Suppresses the next document click in the capture phase.
 *
 * dnd-kit fires a trailing `click` after a drag ends; this prevents that
 * ghost click from reaching click handlers on the dragged element.
 */
export function suppressNextDocumentClick(): void {
  const browserWindow = getBrowserWindow();
  if (!browserWindow) {
    return;
  }
  const doc = browserWindow.document;

  function onClick(event: Event) {
    event.preventDefault();
    event.stopPropagation();
    teardown();
  }
  function teardown() {
    doc.removeEventListener("click", onClick, true);
    doc.removeEventListener("pointerdown", teardown, true);
  }

  doc.addEventListener("click", onClick, true);
  doc.addEventListener("pointerdown", teardown, true);

  // The ghost click arrives within the gesture that ended the drag. A drag
  // cancelled via Escape produces none, so the listener cannot wait for the
  // next click indefinitely — it would swallow a real one instead.
  globalThis.setTimeout(teardown, 350);
}

import { type ClassValue, clsx } from "clsx";
import { twMerge } from "tailwind-merge";

/**
 * Utility function to merge Tailwind CSS classes
 *
 * Uses clsx for conditional class names and tailwind-merge to handle conflicts.
 * This is the canonical implementation - use this instead of scattered versions.
 *
 * @param inputs - Class values to merge
 * @returns Merged class string
 *
 * @example
 * ```tsx
 * cn('px-4 py-2', condition && 'bg-blue-500', { 'text-white': isActive })
 * // Returns: "px-4 py-2 bg-blue-500 text-white" (if condition and isActive are true)
 * ```
 */
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

/**
 * Pure frontend debug-enabled resolution.
 * Settings / PHP debugStatus is the product toggle; NODE_ENV is a fallback.
 */

import { getBrowserWindow } from "./browser-env";

export const FLEEKDASH_FORCE_DEBUG_STORAGE_KEY = "fleekdash_force_debug";
export const FLEEKDASH_DEBUG_STORAGE_KEY = "fleekdash_debug";
export const FLEEKDASH_DEBUG_CHANGED_EVENT = "fleekdash:debug-changed";

export interface DebugStatusSlice {
  readonly debug?: boolean;
  readonly force_debug?: boolean | null;
  readonly source?: string;
  readonly wp_debug?: boolean;
}

export interface DebugEnabledInput {
  readonly nodeEnv: string;
  readonly localForceDebug: string | null;
  readonly localSyncedDebug: string | null;
  readonly debugStatus?: DebugStatusSlice | null;
  readonly fleekDashDebug?: boolean;
  readonly metaWpDebug?: boolean;
}

interface FleekDashDebugSlice {
  debug?: boolean;
  debugStatus?: DebugStatusSlice;
  wordPressData?: {
    debug?: boolean;
    debugStatus?: DebugStatusSlice;
  };
}

function parseLocalForceFlag(value: string | null): boolean | null {
  if (value === "1" || value === "true") {
    return true;
  }
  if (value === "0" || value === "false") {
    return false;
  }
  return null;
}

function isExplicitSettingsOff(status: DebugStatusSlice): boolean {
  if (status.debug !== false) {
    return false;
  }
  if (status.force_debug != null) {
    return true;
  }
  return status.source === "database";
}

/**
 * Resolve whether frontend debug logs should run.
 * Priority: local force override, Settings/PHP status, NODE_ENV, FleekDash flags, synced localStorage.
 */
export function resolveFrontendDebugEnabled(input: DebugEnabledInput): boolean {
  const localForce = parseLocalForceFlag(input.localForceDebug);
  if (localForce !== null) {
    return localForce;
  }

  const status = input.debugStatus;
  if (status?.debug === true) {
    return true;
  }
  if (status && isExplicitSettingsOff(status)) {
    return false;
  }

  if (input.nodeEnv === "development") {
    return true;
  }

  if (input.fleekDashDebug === true || input.metaWpDebug === true) {
    return true;
  }

  return input.localSyncedDebug === "true";
}

function readLocalStorageItem(key: string, storage: Storage): string | null {
  try {
    return storage.getItem(key);
  } catch {
    return null;
  }
}

function getFleekDashDebugSlice(): FleekDashDebugSlice | undefined {
  const browserWindow = getBrowserWindow();
  if (!browserWindow) {
    return undefined;
  }
  return (browserWindow as Window & { FleekDash?: FleekDashDebugSlice })
    .FleekDash;
}

export function readNodeEnv(): string {
  // Vite statically defines import.meta.env.MODE in bundled builds; the
  // process.env fallback covers Node tooling (vitest, tsc, scripts). Reading
  // process via globalThis is intentional: a bare `process.env` reference
  // would throw where the global is absent but undeclared.
  const viteMode = (import.meta as { env?: { MODE?: unknown } }).env?.MODE;
  if (typeof viteMode === "string" && viteMode !== "") {
    return viteMode;
  }
  return (
    (globalThis as { process?: { env?: { NODE_ENV?: string } } }).process?.env
      ?.NODE_ENV ?? ""
  );
}

export function readDebugEnabledInput(): DebugEnabledInput {
  const nodeEnv = readNodeEnv();
  const browserWindow = getBrowserWindow();
  if (!browserWindow) {
    return {
      nodeEnv,
      localForceDebug: null,
      localSyncedDebug: null,
    };
  }

  const fleek = getFleekDashDebugSlice();
  const debugStatus =
    fleek?.debugStatus ?? fleek?.wordPressData?.debugStatus ?? null;
  const fleekDashDebug =
    fleek?.debug === true || fleek?.wordPressData?.debug === true;
  const metaWpDebug =
    browserWindow.document.querySelector(
      'meta[name="wp-debug"][content="true"]',
    ) !== null;

  return {
    nodeEnv,
    localForceDebug: readLocalStorageItem(
      FLEEKDASH_FORCE_DEBUG_STORAGE_KEY,
      browserWindow.localStorage,
    ),
    localSyncedDebug: readLocalStorageItem(
      FLEEKDASH_DEBUG_STORAGE_KEY,
      browserWindow.localStorage,
    ),
    debugStatus,
    fleekDashDebug,
    metaWpDebug,
  };
}

export function applyInMemoryDebugEnabled(enabled: boolean): void {
  const fleek = getFleekDashDebugSlice();
  if (!fleek) {
    return;
  }

  fleek.debug = enabled;
  if (fleek.debugStatus) {
    fleek.debugStatus = { ...fleek.debugStatus, debug: enabled };
  }
  if (fleek.wordPressData) {
    fleek.wordPressData.debug = enabled;
    if (fleek.wordPressData.debugStatus) {
      fleek.wordPressData.debugStatus = {
        ...fleek.wordPressData.debugStatus,
        debug: enabled,
      };
    }
  }
}

/**
 * Intelligent Debug System for FleekDash
 * Controls when and how debug logs are executed to prevent performance issues
 */

import { getBrowserWindow } from "./browser-env";
import {
  applyInMemoryDebugEnabled,
  FLEEKDASH_DEBUG_CHANGED_EVENT,
  FLEEKDASH_DEBUG_STORAGE_KEY,
  readDebugEnabledInput,
  resolveFrontendDebugEnabled,
} from "./debug-enabled";

// Debug configuration
interface DebugConfig {
  enabled: boolean;
  logLevel: "debug" | "info" | "warn" | "error";
  maxLogsPerSecond: number;
  consoleOpenDetection: boolean;
  throttleWhenConsoleOpen: boolean;
}

class IntelligentDebugger {
  private config: DebugConfig;
  private readonly logCount: Map<string, number> = new Map();
  private readonly lastLogTime: Map<string, number> = new Map();
  private isConsoleOpen = false;
  private consoleCheckInterval: ReturnType<
    typeof globalThis.setInterval
  > | null = null;

  constructor() {
    this.config = {
      enabled: false,
      logLevel: "debug",
      maxLogsPerSecond: 10,
      consoleOpenDetection: true,
      throttleWhenConsoleOpen: true,
    };

    this.initConsoleDetection();
    this.syncFromEnvironment();
  }

  syncFromEnvironment(): void {
    this.configure({
      enabled: resolveFrontendDebugEnabled(readDebugEnabledInput()),
    });
  }

  /**
   * Detect if console is open (performance optimization)
   */
  private initConsoleDetection() {
    const browserWindow = getBrowserWindow();
    if (!browserWindow || !this.config.consoleOpenDetection) {
      return;
    }

    const devtools = {
      open: false,
      orientation: null as "vertical" | "horizontal" | null,
    };

    const threshold = 160;

    const detectConsole = () => {
      if (
        browserWindow.outerHeight - browserWindow.innerHeight > threshold ||
        browserWindow.outerWidth - browserWindow.innerWidth > threshold
      ) {
        if (!devtools.open) {
          devtools.open = true;
          this.isConsoleOpen = true;
          this.onConsoleOpen();
        }
      } else if (devtools.open) {
        devtools.open = false;
        this.isConsoleOpen = false;
        this.onConsoleClose();
      }
    };

    // Check every 5 seconds (reduced frequency for better performance)
    this.consoleCheckInterval = globalThis.setInterval(detectConsole, 5000);

    // Pause console detection when page is hidden for performance
    const handleVisibilityChange = () => {
      if (this.consoleCheckInterval !== null) {
        globalThis.clearInterval(this.consoleCheckInterval);
        this.consoleCheckInterval = null;
      }

      // Only restart if page is visible
      if (!browserWindow.document.hidden) {
        this.consoleCheckInterval = globalThis.setInterval(detectConsole, 5000);
      }
    };

    browserWindow.document.addEventListener(
      "visibilitychange",
      handleVisibilityChange,
    );

    // Initial check
    detectConsole();
  }

  private onConsoleOpen() {
    if (this.config.throttleWhenConsoleOpen) {
      this.config.maxLogsPerSecond = 5; // Reduce logs when console is open
    }
  }

  private onConsoleClose() {
    if (this.config.throttleWhenConsoleOpen) {
      this.config.maxLogsPerSecond = 10; // Restore normal rate when console is closed
    }
  }

  /**
   * Check if a log should be executed based on throttling rules
   */
  private shouldLog(
    category: string,
    level: "debug" | "info" | "warn" | "error",
  ): boolean {
    if (!this.config.enabled) return false;

    const now = Date.now();
    const lastTime = this.lastLogTime.get(category) || 0;
    const timeDiff = now - lastTime;

    // Reset counters every second
    if (timeDiff > 1000) {
      this.logCount.set(category, 0);
      this.lastLogTime.set(category, now);
    }

    const currentCount = this.logCount.get(category) || 0;

    // Check if we're exceeding the rate limit
    if (currentCount >= this.config.maxLogsPerSecond) {
      return false;
    }

    // Always allow error logs
    if (level === "error") return true;

    // Check log level hierarchy
    const levels = ["debug", "info", "warn", "error"];
    const currentLevelIndex = levels.indexOf(this.config.logLevel);
    const logLevelIndex = levels.indexOf(level);

    if (logLevelIndex < currentLevelIndex) {
      return false;
    }

    // Increment counter
    this.logCount.set(category, currentCount + 1);

    return true;
  }

  /**
   * Smart debug logging with category and throttling
   */
  debug(category: string, message: string, ...args: any[]) {
    if (this.shouldLog(category, "debug")) {
      console.log(`[DEBUG:${category}] ${message}`, ...args);
    }
  }

  info(category: string, message: string, ...args: any[]) {
    if (this.shouldLog(category, "info")) {
      console.info(`[INFO:${category}] ${message}`, ...args);
    }
  }

  warn(category: string, message: string, ...args: any[]) {
    if (this.shouldLog(category, "warn")) {
      console.warn(`[WARN:${category}] ${message}`, ...args);
    }
  }

  error(category: string, message: string, ...args: any[]) {
    if (this.config.enabled) {
      console.error(`[FleekDash][ERROR:${category}] ${message}`, ...args);
      return;
    }
    // Debug off: no debug/info/warn noise, but keep a copy-pasteable error line for support.
    // Extra args (Error objects, API payloads) are omitted to avoid leaking context data.
    console.error(`[FleekDash][ERROR:${category}] ${message}`);
  }

  /**
   * Configure debug settings
   */
  configure(config: Partial<DebugConfig>) {
    this.config = { ...this.config, ...config };
  }

  /**
   * Check if debug is enabled
   */
  get enabled(): boolean {
    return this.config.enabled;
  }

  /**
   * Get current debug statistics
   */
  getStats() {
    return {
      isConsoleOpen: this.isConsoleOpen,
      config: this.config,
      logCounts: Object.fromEntries(this.logCount),
      lastLogTimes: Object.fromEntries(this.lastLogTime),
    };
  }

  /**
   * Clean up resources
   */
  destroy() {
    if (this.consoleCheckInterval !== null) {
      globalThis.clearInterval(this.consoleCheckInterval);
      this.consoleCheckInterval = null;
    }
  }
}

interface SmartDebuggerGlobalSlot {
  __fleekdashSmartDebugger?: IntelligentDebugger;
}

/**
 * Lazy singleton on globalThis — survives Rollup reordering inside platform-core where
 * exported debugLog() can run before a module-level `const` holder is initialized (TDZ).
 */
function getSmartDebugger(): IntelligentDebugger {
  const slot = globalThis as SmartDebuggerGlobalSlot;
  slot.__fleekdashSmartDebugger ??= new IntelligentDebugger();
  return slot.__fleekdashSmartDebugger;
}

function clearSmartDebugger(): void {
  const slot = globalThis as SmartDebuggerGlobalSlot;
  slot.__fleekdashSmartDebugger?.destroy();
  slot.__fleekdashSmartDebugger = undefined;
}

/**
 * Proxy preserves the same surface as IntelligentDebugger for components that import
 * `smartDebugger` directly (e.g. diagnostic pages) while deferring construction.
 */
export const smartDebugger: IntelligentDebugger = new Proxy(
  {} as IntelligentDebugger,
  {
    get(_target, prop, receiver) {
      const inst = getSmartDebugger();
      const value = Reflect.get(inst, prop, receiver);
      if (typeof value === "function") {
        return value.bind(inst);
      }
      return value;
    },
  },
);

// Convenience functions for backward compatibility
export function debugLog(category: string, message: string, ...args: any[]) {
  getSmartDebugger().debug(category, message, ...args);
}

export function debugInfo(category: string, message: string, ...args: any[]) {
  getSmartDebugger().info(category, message, ...args);
}

export function debugWarn(category: string, message: string, ...args: any[]) {
  getSmartDebugger().warn(category, message, ...args);
}

export function debugError(category: string, message: string, ...args: any[]) {
  getSmartDebugger().error(category, message, ...args);
}

// Original debug functions for backward compatibility
export function fleekdash_log(message: string, ...args: any[]) {
  getSmartDebugger().debug("general", message, ...args);
}

export function fleekdash_log_info(message: string, ...args: any[]) {
  getSmartDebugger().info("general", message, ...args);
}

export function fleekdash_log_warn(message: string, ...args: any[]) {
  getSmartDebugger().warn("general", message, ...args);
}

export function fleekdash_log_error(message: string, ...args: any[]) {
  getSmartDebugger().error("general", message, ...args);
}

export function fleekdash_log_debug(message: string, ...args: any[]) {
  getSmartDebugger().debug("general", message, ...args);
}

export function isFrontendDebugEnabled(): boolean {
  return getSmartDebugger().enabled;
}

export function syncSmartDebuggerFromEnvironment(
  enabledOverride?: boolean,
): void {
  if (typeof enabledOverride === "boolean") {
    applyInMemoryDebugEnabled(enabledOverride);
    getSmartDebugger().configure({ enabled: enabledOverride });
    return;
  }
  getSmartDebugger().syncFromEnvironment();
}

function handleDebugChanged(event: Event): void {
  const detail = (event as CustomEvent<{ enabled?: boolean }>).detail;
  if (typeof detail?.enabled === "boolean") {
    syncSmartDebuggerFromEnvironment(detail.enabled);
    return;
  }
  syncSmartDebuggerFromEnvironment();
}

// Clean up on page unload (resolve window per attachment; do not cache SSR null).
(() => {
  const unloadTarget = getBrowserWindow();
  if (!unloadTarget) {
    return;
  }
  unloadTarget.addEventListener("beforeunload", () => {
    clearSmartDebugger();
  });
  unloadTarget.addEventListener(
    FLEEKDASH_DEBUG_CHANGED_EVENT,
    handleDebugChanged,
  );
  // Cross-tab sync: another tab toggling debug writes localStorage without the
  // in-page event — the "storage" event only fires on the *other* tabs.
  unloadTarget.addEventListener("storage", (event: StorageEvent) => {
    if (event.key === FLEEKDASH_DEBUG_STORAGE_KEY) {
      syncSmartDebuggerFromEnvironment();
    }
  });
})();

import { debugWarn } from "./debug";
import { getBrowserWindow } from "./browser-env";

const ICONIFY_API_HOSTS = [
  "api.iconify.design",
  "api.simplesvg.com",
  "api.unisvg.com",
] as const;

type FleekDashGlobal = typeof globalThis & {
  __fleekdashIconifyFetchGuard__?: boolean;
};

/**
 * Blocks external Iconify CDN fetches (offline bundle only).
 * Installed from platform apiClient boot so production stack traces are not
 * attributed to vendor-iconify when unrelated REST calls fail.
 */
export function installIconifyFetchGuard(): void {
  const browserWindow = getBrowserWindow();
  if (!browserWindow || typeof browserWindow.fetch !== "function") {
    return;
  }

  const fleekGlobal = globalThis as FleekDashGlobal;
  if (fleekGlobal.__fleekdashIconifyFetchGuard__) {
    return;
  }
  fleekGlobal.__fleekdashIconifyFetchGuard__ = true;

  const originalFetch = browserWindow.fetch.bind(browserWindow);
  browserWindow.fetch = (input: RequestInfo | URL, init?: RequestInit) => {
    let url = "";
    if (typeof input === "string") {
      url = input;
    } else if (input instanceof URL) {
      url = input.href;
    } else {
      url = input.url;
    }

    if (ICONIFY_API_HOSTS.some((host) => url.includes(host))) {
      debugWarn("MAIN", "Blocked external Iconify fetch (use local bundle)", {
        url,
      });
      return Promise.resolve(
        new Response("{}", {
          status: 404,
          statusText: "External Iconify API disabled",
        }),
      );
    }

    return originalFetch(input, init);
  };
}

