/**
 * Instant Translation System
 *
 * Ultra-fast translation system that works with pre-injected translations
 * to eliminate any flash of untranslated content
 */

type InstantTranslationState = {
  translationCache: Map<string, string>;
  overridesCache: Map<string, string>;
  translationsInitialized: boolean;
  overridesInitialized: boolean;
};

type GlobalRoot = object;

function getGlobalRoot(): GlobalRoot {
  const browserWindow = getBrowserWindow();
  if (browserWindow) {
    return browserWindow;
  }

  return globalThis;
}

function getState(): InstantTranslationState {
  const root = getGlobalRoot();
  const stateKey = "__fleekdashInstantTranslationState__";
  const existingState = Reflect.get(root, stateKey);

  if (!existingState) {
    const initialState = {
      translationCache: new Map<string, string>(),
      overridesCache: new Map<string, string>(),
      translationsInitialized: false,
      overridesInitialized: false,
    } satisfies InstantTranslationState;

    Reflect.set(root, stateKey, initialState);
  }

  return Reflect.get(root, stateKey) as InstantTranslationState;
}

/**
 * Initialize instant translations from pre-injected data
 */
function initializeInstantTranslations(): void {
  const state = getState();

  if (state.translationsInitialized) return;

  const browserWindow = getBrowserWindow();
  if (!browserWindow) return;

  // Get pre-injected translation data
  const translationData =
    (browserWindow as any).fleekDashI18n?.localeData ||
    (browserWindow as any).FleekDash?.i18n?.localeData;

  if (translationData?.locale_data?.["fleekdash"]) {
    const translations = translationData.locale_data["fleekdash"];

    // Pre-populate cache with all translations
    for (const [key, value] of Object.entries(translations)) {
      if (key !== "" && Array.isArray(value) && value.length > 0) {
        state.translationCache.set(key, value[0] as string);
      }
    }

    state.translationsInitialized = true;
  }
}

/**
 * Initialize text overrides from pre-injected data (en_US only)
 */
function initializeTextOverrides(): void {
  const state = getState();

  if (state.overridesInitialized) return;

  const browserWindow = getBrowserWindow();
  if (!browserWindow) return;

  // Get pre-injected text overrides data
  const overrides =
    (browserWindow as any).FleekDash?.i18n?.textOverrides ||
    (browserWindow as any).fleekDashI18n?.textOverrides;

  if (overrides && typeof overrides === "object") {
    // Pre-populate cache with all overrides
    for (const [key, value] of Object.entries(overrides)) {
      if (key && value) {
        state.overridesCache.set(key, value as string);
      }
    }

    state.overridesInitialized = true;
  }
}

/**
 * Ultra-fast instant translation with placeholder support
 *
 * @param text - Text to translate (can contain placeholders like %s, %1$s, %2$s)
 * @param replacements - Values to replace placeholders with
 *
 * @example
 * instantTranslate('%s Growth Score', 'October')
 * // Example (PT-BR): growth score with %s replaced by localized month name
 * // EN-US (with override): "Dashboard" -> "Control Panel"
 */
export function instantTranslate(
  text: string,
  ...replacements: (string | number)[]
): string {
  // Initialize if not done yet
  const state = getState();

  if (!state.translationsInitialized) {
    initializeInstantTranslations();
  }
  if (!state.overridesInitialized) {
    initializeTextOverrides();
  }

  // For en_US: Check text overrides first (performance optimization)
  const currentLocale = getCurrentLocaleInstant();
  let translated = text;

  if (currentLocale === "en_US") {
    // Check custom text overrides (en_US only)
    translated = state.overridesCache.get(text) || text;
  } else {
    // Check translations (other locales)
    translated = state.translationCache.get(text) || text;
  }

  // Replace placeholders if provided
  if (replacements.length > 0) {
    // Support for both %s and numbered placeholders like %1$s, %2$s
    replacements.forEach((replacement, index) => {
      // Replace numbered placeholders first (%1$s, %2$s, etc)
      translated = translated.replace(`%${index + 1}$s`, () =>
        String(replacement),
      );
      // Then replace simple %s in order
      translated = translated.replace("%s", () => String(replacement));
    });
  }

  return translated;
}

/**
 * Check if instant translations are ready
 */
export function areInstantTranslationsReady(): boolean {
  return (
    getState().translationsInitialized ||
    (() => {
      const browserWindow = getBrowserWindow();
      return !!(
        browserWindow &&
        ((browserWindow as any).fleekDashI18n?.localeData ||
          (browserWindow as any).FleekDash?.i18n?.localeData)
      );
    })()
  );
}

/**
 * Get current locale instantly
 */
export function getCurrentLocaleInstant(): string {
  const browserWindow = getBrowserWindow();
  if (!browserWindow) return "en_US";

  return (
    (browserWindow as any).fleekDashI18n?.locale ||
    (browserWindow as any).FleekDash?.i18n?.locale ||
    (browserWindow as any).FleekDash?.locale ||
    "en_US"
  );
}

/**
 * Get configured WooCommerce currency code (or fallback) from pre-injected payload
 */
export function getCurrentCurrencyCodeInstant(): string {
  const browserWindow = getBrowserWindow();
  if (!browserWindow) return "USD";

  return (
    (browserWindow as any).fleekDashI18n?.currencyCode ||
    (browserWindow as any).FleekDash?.i18n?.currencyCode ||
    "USD"
  );
}

function attachLocaleChangeListener(): void {
  const localeBrowserWindow = getBrowserWindow();
  if (!localeBrowserWindow) {
    return;
  }
  localeBrowserWindow.addEventListener("fleekdash:locale-changed", () => {
    const state = getState();
    state.translationsInitialized = false;
    state.overridesInitialized = false;
    state.translationCache.clear();
    state.overridesCache.clear();
    initializeInstantTranslations();
    initializeTextOverrides();
  });
}

function runDeferredInstantTranslateInit(): void {
  initializeInstantTranslations();
  initializeTextOverrides();
  attachLocaleChangeListener();
}

// Initialize shortly after module load (after module state is created)
if (typeof queueMicrotask === "function") {
  queueMicrotask(runDeferredInstantTranslateInit);
} else {
  // prettier-ignore -- keep block unchanged so formatter does not reflow and Sonar suppression stays effective
  Promise.resolve().then(runDeferredInstantTranslateInit); // NOSONAR S7785: build target es2020 does not support top-level await
}

import { createContext, useContext, useMemo } from "react";

export interface OverlayEnvironmentValue {
  containerId?: string;
}

const OverlayEnvironmentContext = createContext<OverlayEnvironmentValue>({});

export interface OverlayEnvironmentProviderProps {
  containerId?: string;
  children: React.ReactNode;
}

export function OverlayEnvironmentProvider({
  containerId,
  children,
}: OverlayEnvironmentProviderProps) {
  const value = useMemo(
    () => ({
      containerId: containerId?.trim() || undefined,
    }),
    [containerId],
  );

  return (
    <OverlayEnvironmentContext.Provider value={value}>
      {children}
    </OverlayEnvironmentContext.Provider>
  );
}

export function useOverlayEnvironment(): OverlayEnvironmentValue {
  return useContext(OverlayEnvironmentContext);
}

/**
 * Overlay registry utilities
 *
 * Provides a simple registry to keep track of open overlays (popover, tooltip, etc.)
 * associated with a logical container (like a Vaul drawer). This allows us to
 * close overlays proactively when the container is hidden.
 *
 * @layer Platform
 */
import { debugError } from "../debug";

type OverlayCloser = () => void;

function logOverlayCloseError(containerId: string, error: unknown): void {
  debugError(
    "MAIN",
    "[OverlayRegistry] Failed to close overlay for container",
    containerId,
    error,
  );
}

const overlayRegistry = new Map<string, Set<OverlayCloser>>();

export function registerOverlay(containerId: string, closer: OverlayCloser) {
  if (!containerId) return;

  const normalizedId = containerId.trim();
  if (!normalizedId) return;

  let closers = overlayRegistry.get(normalizedId);
  if (!closers) {
    closers = new Set();
    overlayRegistry.set(normalizedId, closers);
  }

  closers.add(closer);
}

export function unregisterOverlay(containerId: string, closer: OverlayCloser) {
  if (!containerId) return;

  const normalizedId = containerId.trim();
  const closers = overlayRegistry.get(normalizedId);
  if (!closers) return;

  closers.delete(closer);
  if (closers.size === 0) {
    overlayRegistry.delete(normalizedId);
  }
}

export function closeOverlaysForContainer(containerId?: string) {
  if (!containerId) return;

  const normalizedId = containerId.trim();
  if (!normalizedId) return;

  const closers = overlayRegistry.get(normalizedId);
  if (!closers) return;

  closers.forEach((close) => {
    try {
      close();
    } catch (error) {
      logOverlayCloseError(normalizedId, error);
    }
  });
}

/**
 * Reads `data-theme` from the document root.
 *
 * Pure DOM helper — lives in platform so design-system Button code never imports
 * `theme-dom` (which Rollup may co-locate with domain-posts and create TDZ cycles).
 */
export function readRootDataThemeAttribute(
  root: HTMLElement = document.documentElement,
): string | null {
  const attr = root.attributes.getNamedItem("data-theme");
  return attr?.value ?? null;
}

/**
 * Creates a squircle mask for an element using dynamic SVG masking
 * Based on the approach from https://codepen.io/
 */
interface SquircleOptions {
  cornerSize?: number;
  curvature?: number;
}

/**
 * Applies a squircle mask to the given element
 * @param element The element to apply the squircle mask to
 * @param options Optional parameters for customizing the squircle
 */
export function makeSquircle(
  element: HTMLElement,
  options: SquircleOptions = {},
): void {
  // Get options from element attributes or use defaults
  let cornerSize = options.cornerSize;
  let curvature = options.curvature;

  // Use CSS variables if available, otherwise use provided options or defaults
  if (!cornerSize) {
    const cornerSizeVar = getComputedStyle(element)
      .getPropertyValue("--squircle-corner-size")
      .trim();
    cornerSize = cornerSizeVar ? parseInt(cornerSizeVar, 10) : 18;
  }

  if (!curvature) {
    const curvatureVar = getComputedStyle(element)
      .getPropertyValue("--squircle-curvature")
      .trim();
    curvature = curvatureVar ? parseInt(curvatureVar, 10) : 6;
  }

  // Get element dimensions
  const height = element.offsetHeight;
  const width = element.offsetWidth;

  // Calculate the midpoint of the shortest side
  const half = height > width ? width / 2 : height / 2;

  // Make sure corner size isn't bigger than half the shortest dimension
  const cornerAnchor = half < cornerSize ? half : cornerSize;

  // Calculate the length of the straight horizontal and vertical paths
  const hSides = width - cornerAnchor * 2;
  const vSides = height - cornerAnchor * 2;

  // Generate SVG mask for the squircle
  const svgMask = `url("data:image/svg+xml,<svg version='1.1' xmlns='http://www.w3.org/2000/svg' xml:space='preserve' width='${width}' height='${height}' viewBox='0 0 ${width} ${height}'><path d='M0,${cornerAnchor} C0,${curvature} ${curvature},0 ${cornerAnchor},0 h${hSides} c${
    cornerAnchor - curvature
  },0 ${cornerAnchor},${curvature} ${cornerAnchor},${cornerAnchor} v${vSides} c0,${
    cornerAnchor - curvature
  } -${curvature},${cornerAnchor} -${cornerAnchor},${cornerAnchor} h-${hSides} c-${
    cornerAnchor - curvature
  },0 -${cornerAnchor},-${curvature} -${cornerAnchor},-${cornerAnchor} v-${vSides}Z'></path></svg>")`;

  // Apply the mask as a CSS variable
  element.style.setProperty("--squircle-mask", svgMask);

  // Add the mask-squircle class if it doesn't exist
  if (!element.classList.contains("mask-squircle")) {
    element.classList.add("mask-squircle");
  }
}

/**
 * Applies squircle masks to all elements with the 'squircle' class
 * Optional: Add a mutation observer to handle dynamically added elements
 */
export function applySquirclesToElements(): void {
  // Select all elements with the squircle class
  const elements = document.querySelectorAll(
    ".squircle",
  ) as NodeListOf<HTMLElement>;

  // Apply squircle to each element
  elements.forEach((element) => {
    makeSquircle(element);
  });
}

// For debugging in browser console
if (typeof window !== "undefined") {
  (window as any).makeSquircle = makeSquircle;
  (window as any).applySquirclesToElements = applySquirclesToElements;
}

/**
 * Minimal theme-facing types for Fleek UI.
 * Subset of `@platform/theme/types` — kept tiny so the package never
 * needs the shell's full theme type surface.
 */
export type IconLibrary = "solar" | "lucide";

import { useEffect, useState } from "react";

/**
 * Hook to debounce values
 *
 * @param value - Value to debounce
 * @param delay - Delay in milliseconds
 * @returns Debounced value
 *
 * @example
 * ```tsx
 * const [searchTerm, setSearchTerm] = useState('');
 * const debouncedSearchTerm = useDebounce(searchTerm, 300);
 *
 * useEffect(() => {
 *   if (debouncedSearchTerm) {
 *     // Run search after 300ms of inactivity
 *     searchAPI(debouncedSearchTerm);
 *   }
 * }, [debouncedSearchTerm]);
 * ```
 */
export function useDebounce<T>(value: T, delay: number): T {
  const [debouncedValue, setDebouncedValue] = useState<T>(value);

  useEffect(() => {
    const timer = setTimeout(() => {
      setDebouncedValue(value);
    }, delay);

    return () => {
      clearTimeout(timer);
    };
  }, [value, delay]);

  return debouncedValue;
}
